/* No libm in here on purpose: sinf / cosf / powf / expf / fmodf are slow software on the Fire's chip
 * (measured: PLASMA took 3163 us per 16 pads). Sines are a short polynomial, the three power / exp
 * curves are lookup tables (lights_tab.h, generated by gen_lights_tab.py), and wrap-arounds use
 * float arithmetic only. After building, `arm-none-eabi-nm lights.o` must list no sinf / powf / expf
 * / fmodf / floorf. lights_test.c + lights_vs_orc.py check all of it against the real maths. */
#include <string.h>
#include "lights.h"
#include "lights_tab.h"

#define PI_F 3.14159265f
#define HALF_PI_F 1.57079633f
#define TWO_PI_F 6.28318531f

const char *const LT_NAME[LT_MODES] = {
    "Plasma", "Sparkle", "Sweep", "Flame", "Beat", "Sparse", "Rain", "Ripple", "Comet", "Scanner", "Wave", "-",   /* 11 = the old fake VU, removed */
    "Tracks", "Host", "Text",
};

/* The ORC's per-mode pace (_PL_SPEED_SCALE). */
static const float SCALE[LT_MODES] = {0.4f, 0.4f, 0.4f, 1.0f, 0.4f, 0.4f, 0.5f, 0.5f, 0.6f, 0.5f, 0.4f, 0.4f, 1.0f, 1.0f, 1.0f};
float lights_scale(int mode) { return (mode >= 0 && mode < LT_MODES) ? SCALE[mode] : 1.0f; }

/* square root: the chip's own instruction (the library sqrtf is a call that also sets errno).
   The host build (lights_test, on the Pi or a PC) takes the #else branch. That still tests the code that ships:
   IEEE 754 requires square root to be CORRECTLY ROUNDED, so the Fire's vsqrt.f32 (round-to-nearest: the FPSCR is
   left at its reset value, no flush-to-zero) and the host's sqrtf / fsqrt / sqrtss give the same bits for every
   input. The only gap is a negative input (errno, NaN), and both callers (PLASMA, RIPPLE) pass a sum of squares, which never
   is. Checked 2026-10-13: lights.o for the Fire contains vsqrt.f32 and lists only memset as undefined (no libm). */
static float fsqrt(float x)
{
#if defined(__ARM_ARCH_7EM__) && defined(__ARM_FP) && (__ARM_FP & 4)   /* the Fire (Cortex-M4F) only */
    float r;
    __asm__("vsqrt.f32 %0, %1" : "=t"(r) : "t"(x));
    return r;
#else
    return __builtin_sqrtf(x);
#endif
}
static float fminf_(float a, float b) { return a < b ? a : b; }
static float fmaxf_(float a, float b) { return a > b ? a : b; }
static float fabsf_(float a) { return a < 0 ? -a : a; }
static float clampf(float v, float lo, float hi) { return v < lo ? lo : v > hi ? hi : v; }
static uint8_t u8(float x) { x = clampf(x, 0.0f, 1.0f); return (uint8_t)(x * 255.0f + 0.5f); }

/* a modulo m, always 0 <= result < m (float arithmetic only) */
static float pmod(float a, float m)
{
    float r = a - m * (float)(int)(a / m);
    if (r < 0) r += m;
    if (r >= m) r -= m;
    return r;
}

/* sine: wrap to -pi..pi (two-part 2pi so large arguments stay accurate), fold to -pi/2..pi/2, then the
   Taylor series to x^9 (error under 4e-6 there). */
float lights_fsin(float x)
{
    float q = x * 0.15915494f;
    int k = (int)(q + (q >= 0 ? 0.5f : -0.5f));
    x -= (float)k * 6.28125f;
    x -= (float)k * 0.0019353072f;
    if (x > HALF_PI_F) x = PI_F - x;
    else if (x < -HALF_PI_F) x = -PI_F - x;
    float x2 = x * x;
    return x * (1.0f + x2 * (-1.6666667e-1f + x2 * (8.3333333e-3f + x2 * (-1.9841270e-4f + x2 * 2.7557319e-6f))));
}
static float fcos(float x) { return lights_fsin(x + HALF_PI_F); }

/* table lookup with linear interpolation, x in 0..1 */
static float tab(const float *T, int n, float x)
{
    float p = clampf(x, 0.0f, 1.0f) * (float)(n - 1);
    int i = (int)p;
    if (i >= n - 1) return T[n - 1];
    return T[i] + (T[i + 1] - T[i]) * (p - (float)i);
}

float lights_speed_factor(int v)                    /* 2^((v-64)/32) */
{
    int e = (v < 0 ? 0 : v > 127 ? 127 : v) - 64;
    int oct = e >= 0 ? e / 32 : -((-e + 31) / 32);   /* floor(e / 32) */
    float f = TAB_SPEED32[e - oct * 32];
    for (; oct > 0; oct--) f *= 2.0f;
    for (; oct < 0; oct++) f *= 0.5f;
    return f;
}

/* HSV -> RGB (h wraps; s, v 0..1), the same colour wheel as the ORC's _hsv. */
static void hsv(float h, float s, float v, uint8_t *o)
{
    h = pmod(h, 1.0f);
    float h6 = h * 6.0f;
    int i = (int)h6;
    float f = h6 - (float)i;
    float p = v * (1 - s), q = v * (1 - f * s), t = v * (1 - (1 - f) * s), r, g, b;
    switch (i % 6) {
    case 0: r = v; g = t; b = p; break;
    case 1: r = q; g = v; b = p; break;
    case 2: r = p; g = v; b = t; break;
    case 3: r = p; g = q; b = v; break;
    case 4: r = t; g = p; b = v; break;
    default: r = v; g = p; b = q; break;
    }
    o[0] = u8(r); o[1] = u8(g); o[2] = u8(b);
}
static void black(uint8_t *o) { o[0] = o[1] = o[2] = 0; }

/* ---- the data-driven bars ---- */
static float hit_bar[LT_COLS], hit_peak[LT_COLS], host_bar[LT_COLS], host_peak[LT_COLS];
/* The host's bars FOLLOW the level it sends (smoothly both ways), they don't jump to each reading and fall in a
   line: that ratchet made the tops of the bars hop (measured on a real recording, host_vu_tops.py: lit-pad hops
   3.4 -> 1.3 per second per bar, top-pad brightness steps 14.5 -> 6.1, peak-dot hops 2.1 -> 0.8). */
static float host_tgt[LT_COLS], host_hold[LT_COLS], host_age;
#define HOST_UP_TAU 0.06f                           /* seconds to follow a rising level */
#define HOST_DOWN_TAU 0.16f                         /* ... and a falling one */
#define HOST_PEAK_HOLD 0.4f                         /* the peak dot waits this long, */
#define HOST_PEAK_FALL 0.3f                         /* then falls this much of the full height per second */

/* Bars are WHOLE pads (a partly lit top pad was the flicker). The lit count has hysteresis: pad k lights when the
   bar reaches k - 0.35 pads and goes out only below k - 0.65, so a bar sitting on a boundary doesn't chatter. */
static int stick_rows(int cur, float h)
{
    float h4 = h * (float)LT_ROWS;
    while (cur < LT_ROWS && h4 >= (float)(cur + 1) - 0.35f) cur++;
    while (cur > 0 && h4 < (float)cur - 0.65f) cur--;
    return cur;
}
static int hit_rows[LT_COLS], host_rows[LT_COLS];
static int bar_style;                               /* 0 snappy, 1 smooth, 2 whole (see lights.h) */
void lights_set_bar_style(int st)
{
    st = st < 0 ? 0 : st > 4 ? 4 : st;
    if (st != bar_style) lights_clear_bars();   /* a look's state (hold, sticky rows) means nothing to another look */
    bar_style = st;
}
static int snappy(void) { return bar_style == 0 || bar_style == 3; }   /* the looks that jump to the level and fall in a line */

void lights_clear_bars(void)
{
    memset(hit_bar, 0, sizeof hit_bar); memset(hit_peak, 0, sizeof hit_peak);
    memset(host_bar, 0, sizeof host_bar); memset(host_peak, 0, sizeof host_peak);
    memset(host_tgt, 0, sizeof host_tgt); memset(host_hold, 0, sizeof host_hold);
    memset(hit_rows, 0, sizeof hit_rows); memset(host_rows, 0, sizeof host_rows);
    host_age = 0;
}

void lights_hit(int track, int lv)
{
    if (track < 0 || track > 23 || lv < 1) return;
    int c = track & 15;
    float h = lv >= 3 ? 1.0f : lv == 2 ? 0.7f : 0.4f;
    if (h > hit_bar[c]) hit_bar[c] = h;
    if (h > hit_peak[c]) hit_peak[c] = h;
}

void lights_host(const uint8_t lv[16])
{
    for (int c = 0; c < LT_COLS; c++) {
        float h = clampf((float)(lv[c] & 127) / 127.0f, 0.0f, 1.0f);
        host_tgt[c] = h;
        if (snappy()) {                             /* snappy: the bar and its peak jump straight to a higher level */
            if (h > host_bar[c]) host_bar[c] = h;
            if (h > host_peak[c]) host_peak[c] = h;
        }
    }
    host_age = 0.0f;
}

void lights_step(float dt)
{
    for (int c = 0; c < LT_COLS; c++) {
        hit_bar[c] = fmaxf_(0.0f, hit_bar[c] - dt * 1.6f);
        hit_peak[c] = fmaxf_(hit_bar[c], hit_peak[c] - dt * 0.45f);
        hit_rows[c] = stick_rows(hit_rows[c], hit_bar[c]);
    }
    host_age += dt;
    if (snappy()) {                                 /* snappy: fall in a straight line, the peak dot falls after it */
        for (int c = 0; c < LT_COLS; c++) {
            host_bar[c] = fmaxf_(0.0f, host_bar[c] - dt * 1.2f);
            host_peak[c] = fmaxf_(host_bar[c], host_peak[c] - dt * 0.45f);
            host_rows[c] = stick_rows(host_rows[c], host_bar[c]);
        }
        return;
    }
    float ku = dt / (HOST_UP_TAU + dt), kd = dt / (HOST_DOWN_TAU + dt);       /* first-order following, stable for any dt */
    for (int c = 0; c < LT_COLS; c++) {
        if (host_age > 0.5f) host_tgt[c] = fmaxf_(0.0f, host_tgt[c] - dt * 1.2f);   /* the host went quiet: let go */
        float t = host_tgt[c];
        host_bar[c] += (t - host_bar[c]) * (t > host_bar[c] ? ku : kd);
        if (t == 0.0f && host_bar[c] < 0.01f) host_bar[c] = 0.0f;                /* following toward 0 never quite arrives: snap */
        if (host_bar[c] >= host_peak[c]) { host_peak[c] = host_bar[c]; host_hold[c] = HOST_PEAK_HOLD; }
        else if (host_hold[c] > 0.0f) host_hold[c] -= dt;
        else host_peak[c] = fmaxf_(host_bar[c], host_peak[c] - dt * HOST_PEAK_FALL);
        host_rows[c] = stick_rows(host_rows[c], host_bar[c]);
    }
}

/* The heat-sheet colour scale: warmth 0 (cold: black) -> purple -> blue -> cyan -> green -> yellow -> orange -> red (hot). */
static const struct { float w, hue; } HEAT[9] = {
    {0.00f, 0.80f}, {0.10f, 0.76f}, {0.24f, 0.68f}, {0.38f, 0.58f}, {0.50f, 0.46f}, {0.62f, 0.34f}, {0.74f, 0.17f}, {0.87f, 0.07f}, {1.00f, 0.00f},
};
void lights_heat_rgb(float v, uint8_t *o)
{
    v = clampf(v, 0.0f, 1.0f);
    int i = 0;
    while (i < 7 && v > HEAT[i + 1].w) i++;
    float t = (v - HEAT[i].w) / (HEAT[i + 1].w - HEAT[i].w);
    float hue = HEAT[i].hue + (HEAT[i + 1].hue - HEAT[i].hue) * t;
    hsv(hue, 1.0f, fminf_(1.0f, v / 0.10f) * 0.95f, o);    /* starts BLACK when cold, full brightness by 10% warmth */
}
#define HEAT_DEPTH 3.2f                             /* pads of depth that make a pad fully hot */
static int heat_flip;
void lights_set_heat_flip(int on) { heat_flip = on ? 1 : 0; }

/* One pad of a bar of height h (0..1, `rows` = its whole-pad count): green at the bottom to red at the top, and a dim
   peak pad above it. Styles 0 and 1 light the top pad by how much of it the bar covers; style 2 lights whole pads. */
static void bar_pad(float h, int rows, float peak, int row, uint8_t *o)
{
    int fb = LT_ROWS - 1 - row;                     /* rows up from the bottom */
    if (bar_style == 2) {
        int pk = (int)(peak * (float)LT_ROWS + 0.35f);   /* the SAME turn-on point as the bar's, so a peak equal to the bar draws no dot */
        if (fb < rows) hsv(0.33f * (1.0f - (float)fb / (float)(LT_ROWS - 1)), 1.0f, 0.9f, o);
        else if (pk > rows && fb == pk - 1) hsv(0.0f, 0.0f, 0.45f, o);
        else black(o);
        return;
    }
    if (bar_style >= 3) {                           /* heat: a pad's warmth = how deep inside the bar it is */
        float depth = h * (float)LT_ROWS - (float)fb;
        if (depth > 0.04f) {
            /* normal: warmth = how deep inside the bar (hot base, cool tip). flipped: the height the pad's covered part reaches */
            float w = heat_flip ? ((float)fb + fminf_(depth, 1.0f)) / (float)LT_ROWS : depth / HEAT_DEPTH;
            lights_heat_rgb(w, o);
        }
        else if (peak > 0.05f && (int)(peak * (float)LT_ROWS - 0.001f) == fb) hsv(0.0f, 0.0f, 0.45f, o);
        else black(o);
        return;
    }
    float cover = clampf(h * (float)LT_ROWS - (float)fb, 0.0f, 1.0f);
    if (cover > 0.04f) {                            /* (a speck of a bar lights nothing) */
        hsv(0.33f * (1.0f - (float)fb / (float)(LT_ROWS - 1)), 1.0f, 0.2f + 0.7f * cover, o);
    } else if (peak > 0.05f && (int)(peak * (float)LT_ROWS - 0.001f) == fb) {
        hsv(0.0f, 0.0f, 0.45f, o);
    } else black(o);
}

/* ---- the scrolling text: a 3x4 font (the pads are only 4 rows tall) ----
   A glyph is 4 rows of 3 bits, packed row0 << 9 | row1 << 6 | row2 << 3 | row3, bit 2 = the left column.
   Letters are drawn as capitals; W and M differ in their top row; '~' is a heart. */
#define GL(a, b, c, d) ((uint16_t)(((a) << 9) | ((b) << 6) | ((c) << 3) | (d)))
static const struct { char c; uint16_t g; } FONT[] = {
    {'A', GL(2, 5, 7, 5)}, {'B', GL(6, 7, 5, 6)}, {'C', GL(3, 4, 4, 3)}, {'D', GL(6, 5, 5, 6)}, {'E', GL(7, 6, 4, 7)},
    {'F', GL(7, 6, 4, 4)}, {'G', GL(3, 4, 5, 3)}, {'H', GL(5, 7, 5, 5)}, {'I', GL(7, 2, 2, 7)}, {'J', GL(3, 1, 5, 2)},
    {'K', GL(5, 6, 5, 5)}, {'L', GL(4, 4, 4, 7)}, {'M', GL(5, 7, 7, 5)}, {'N', GL(6, 5, 5, 5)}, {'O', GL(2, 5, 5, 2)},
    {'P', GL(6, 5, 6, 4)}, {'Q', GL(2, 5, 5, 3)}, {'R', GL(6, 5, 6, 5)}, {'S', GL(3, 6, 1, 6)}, {'T', GL(7, 2, 2, 2)},
    {'U', GL(5, 5, 5, 7)}, {'V', GL(5, 5, 5, 2)}, {'W', GL(5, 5, 7, 5)}, {'X', GL(5, 5, 2, 5)}, {'Y', GL(5, 5, 2, 2)},
    {'Z', GL(7, 1, 4, 7)},
    {'0', GL(7, 5, 5, 7)}, {'1', GL(2, 6, 2, 7)}, {'2', GL(6, 1, 2, 7)}, {'3', GL(6, 3, 1, 6)}, {'4', GL(5, 5, 7, 1)},
    {'5', GL(7, 6, 1, 6)}, {'6', GL(3, 6, 5, 2)}, {'7', GL(7, 1, 2, 2)}, {'8', GL(2, 7, 5, 7)}, {'9', GL(2, 5, 3, 6)},
    {'!', GL(2, 2, 0, 2)}, {'?', GL(6, 1, 0, 2)}, {'.', GL(0, 0, 0, 2)}, {',', GL(0, 0, 2, 4)}, {'-', GL(0, 7, 0, 0)},
    {':', GL(0, 2, 0, 2)}, {'\'', GL(2, 2, 0, 0)}, {'+', GL(0, 2, 7, 2)}, {'/', GL(1, 2, 2, 4)}, {'=', GL(7, 0, 7, 0)},
    {'~', GL(5, 7, 7, 2)}, {'*', GL(5, 2, 5, 0)}, {'#', GL(5, 7, 5, 7)},
};
static char text_buf[LT_TEXT_MAX + 1] = "HELLO";
static int text_len = 5;
static float text_t0;                               /* the effect time the message started at (it restarts from the right edge) */
static int text_started;

void lights_set_text(const char *s, int n)
{
    int k = 0;
    for (int i = 0; i < n && k < LT_TEXT_MAX; i++) {
        char ch = s[i];
        if (ch >= 'a' && ch <= 'z') ch = (char)(ch - 32);
        text_buf[k++] = (ch >= 32 && ch <= 126) ? ch : ' ';
    }
    text_buf[k] = 0;
    text_len = k;
    text_started = 0;                               /* the next frame restarts the scroll */
}

const char *lights_text(void) { return text_buf; }

static uint16_t glyph_of(char ch)
{
    for (unsigned i = 0; i < sizeof FONT / sizeof FONT[0]; i++) if (FONT[i].c == ch) return FONT[i].g;
    return 0;                                       /* a space, or anything the font lacks */
}

/* The message strip: each character is 3 columns + a gap; after the last one comes a 16-column gap so
   the message repeats with room between. Column m of the strip -> 4 bits (row 0 = bit 3 .. row 3 = bit 0). */
static int strip_len(void) { return text_len * 4 + LT_COLS; }
static int strip_col(int m)
{
    if (m < 0 || m >= text_len * 4) return 0;
    int ci = m >> 2, gc = m & 3;
    if (gc == 3) return 0;                          /* the gap */
    uint16_t g = glyph_of(text_buf[ci]);
    int bit = 2 - gc, v = 0;                        /* the glyph's column gc: bit (2 - gc) of each row */
    for (int r = 0; r < 4; r++) if ((g >> ((3 - r) * 3 + bit)) & 1) v |= 8 >> r;
    return v;
}

/* x^8 and x^20 for x in 0..1, by multiplication */
static float pow8(float x) { x *= x; x *= x; return x * x; }
static float pow20(float x) { float x2 = x * x, x4 = x2 * x2, x8 = x4 * x4, x16 = x8 * x8; return x16 * x4; }

static void pad(int mode, float t, int row, int col, uint8_t *o)
{
    const float fr = (float)row, fc = (float)col;
    switch (mode) {
    case 0: {                                       /* PLASMA */
        float v = lights_fsin(fc * 0.55f + t) + lights_fsin(fr * 1.4f + t * 1.3f) + lights_fsin((fc + fr) * 0.45f + t * 0.8f)
                + lights_fsin(fsqrt(fc * fc + fr * fr + 0.5f) * 0.7f + t * 1.1f);
        float b = 0.6f + 0.4f * lights_fsin(t * 2.5f + fc * 0.4f + fr * 0.9f);
        hsv(v * 0.125f + 0.5f, 1.0f, b, o);
        break;
    }
    case 1: {                                       /* SPARKLE */
        float rate = 0.7f + (float)((row * 5 + col * 11 + row * col) % 19) * 0.09f;
        float offset = pmod(fr * 7.3f + fc * 13.7f, TWO_PI_F);
        float c = fcos(t * rate + offset);
        float spark = c > 0 ? pow8(c) : 0.0f;
        if (spark < 0.02f) black(o);
        else hsv(offset / TWO_PI_F + t * 0.01f, 0.6f, spark, o);
        break;
    }
    case 2: {                                       /* SWEEP */
        float hue = fc / (float)LT_COLS * 0.75f + t * 0.04f + fr * 0.06f;
        float b = 0.45f + 0.55f * (lights_fsin(fc * 0.45f - t * 1.8f + fr * 0.7f) * 0.5f + 0.5f);
        hsv(hue, 1.0f, b, o);
        break;
    }
    case 3: {                                       /* FLAME */
        float frac = fr / (float)(LT_ROWS - 1);
        float base = 0.35f + 0.65f * frac;
        float flicker = lights_fsin(fc * 2.1f + t * 3.5f) * 0.28f + lights_fsin(fc * 0.8f + t * 2.0f + fr * 0.6f) * 0.18f
                      + lights_fsin(fc * 3.8f + t * 1.5f) * 0.12f;
        float heat = clampf(base + flicker - 0.30f * (1.0f - frac), 0.0f, 1.0f);
        if (heat < 0.04f) black(o);
        else hsv(heat * 0.167f, 1.0f, tab(TAB_POW055, 257, heat), o);
        break;
    }
    case 4: {                                       /* BEAT */
        float beat = pmod(t / 3.0f, 1.0f), bar_hue = pmod(t / 12.0f * 0.25f, 1.0f);
        float local = pmod(beat - fc * (0.6f / (float)LT_COLS), 1.0f);
        float pulse = tab(TAB_EXPM55, 129, local);
        float shimmer = 0.08f * (lights_fsin(t * 0.9f + fr * 1.1f + fc * 0.3f) * 0.5f + 0.5f);
        hsv(bar_hue + fr * 0.25f, 1.0f, fminf_(1.0f, pulse + shimmer), o);
        break;
    }
    case 5: {                                       /* SPARSE */
        float rate = 0.5f + (float)((row * 5 + col * 11 + row * col) % 19) * 0.06f;
        float offset = pmod(fr * 7.3f + fc * 13.7f, TWO_PI_F);
        float c = fcos(t * rate + offset);
        float spark = c > 0 ? pow20(c) : 0.0f;
        if (spark < 0.35f) black(o);
        else hsv(offset / TWO_PI_F, 0.25f, fminf_(1.0f, spark * 1.3f), o);
        break;
    }
    case 6: {                                       /* RAIN */
        const float TRAIL = 3.0f, SPAN = (float)(LT_ROWS + 3);
        float rate = 0.8f + (float)((col * 7) % 5) * 0.12f;
        float head = pmod(t * rate + fc * 1.7f, SPAN);
        float d = head - fr;
        if (d < 0 || d > TRAIL) { black(o); break; }
        float b = 1 - d / TRAIL;
        if (d < 0.55f) hsv(0.34f, 0.25f, fminf_(1.0f, b * 1.2f), o);
        else hsv(0.34f, 0.95f, b * 0.9f, o);
        break;
    }
    case 7: {                                       /* RIPPLE */
        float cx = 7.5f + 6.0f * lights_fsin(t * 0.5f), cy = 1.5f + 1.2f * lights_fsin(t * 0.37f);
        float dy = (fr - cy) * 2.2f, dx = fc - cx, dist = fsqrt(dx * dx + dy * dy);
        float s = lights_fsin(dist * 0.9f - t * 2.0f), b = s > 0 ? s * s : 0.0f;
        if (b < 0.03f) black(o);
        else hsv(dist * 0.03f + t * 0.05f, 0.85f, b, o);
        break;
    }
    case 8: {                                       /* COMET */
        const float N = (float)(LT_ROWS * LT_COLS), TL = 11.0f;
        float head = pmod(t * 6.0f, N);
        float idx = (float)(row * LT_COLS + ((row & 1) ? (LT_COLS - 1 - col) : col));
        float d = pmod(head - idx, N);
        if (d > TL) { black(o); break; }
        float b = tab(TAB_POW16, 129, 1 - d / TL), hue = idx / N + t * 0.1f;
        if (d < 1.0f) hsv(hue, 0.15f, fminf_(1.0f, b * 1.1f), o);
        else hsv(hue, 1.0f, b, o);
        break;
    }
    case 9: {                                       /* SCANNER */
        float p = pmod(t * 3.0f, 2.0f * (float)(LT_COLS - 1));
        float x = p > (float)(LT_COLS - 1) ? 2.0f * (float)(LT_COLS - 1) - p : p;
        float b = fmaxf_(0.0f, 1 - fabsf_(fc - x) / 3.0f);
        b *= b;
        if (b < 0.02f) black(o);
        else hsv(0.015f, 0.9f, b, o);
        break;
    }
    case 10: {                                      /* WAVE */
        float surface = 1.5f + 1.3f * lights_fsin(fc * 0.5f - t * 1.5f);
        float b = fmaxf_(0.0f, 1 - fabsf_(fr - surface) / 1.6f);
        if (b < 0.05f) black(o);
        else hsv(0.55f - 0.08f * b, 0.8f, 0.15f + 0.85f * b, o);
        break;
    }
    case LT_M_HITS: bar_pad(hit_bar[col], hit_rows[col], hit_peak[col], row, o); break;
    case LT_M_HOST: bar_pad(host_bar[col], host_rows[col], host_peak[col], row, o); break;
    case LT_M_TEXT: {
        /* scroll 1.4 columns per effect unit (tempo-locked like the shows, and the speed knob scales it);
           the message starts just off the right edge */
        if (!text_started) { text_t0 = t; text_started = 1; }
        int n = strip_len();
        int p = (int)((t - text_t0) * 1.4f) % n;
        int m = (p + col - LT_COLS + n * 4) % n;
        if (!((strip_col(m) >> (3 - row)) & 1)) { black(o); break; }
        hsv((float)m * 0.045f + t * 0.03f, 0.85f, 0.9f, o);   /* a rainbow that travels with the letters */
        break;
    }
    default: black(o); break;
    }
}

void lights_cols(int mode, float t, int c0, int c1, uint8_t out[][3])
{
    if (c0 < 0) c0 = 0;
    if (c1 > LT_COLS) c1 = LT_COLS;
    for (int col = c0; col < c1; col++)
        for (int row = 0; row < LT_ROWS; row++) pad(mode, t, row, col, out[row * LT_COLS + col]);
}

int lights_level(int v, int row, int col, unsigned frame, int smooth)
{
    if (v <= 0) return 0;
    float x = (float)v / 255.0f;
    float y = x * x * 7.0f;
    int L = (int)y;
    float frac = y - (float)L;
    (void)frame;                                    /* (kept in the signature: the threshold must NOT change per frame) */
    if (smooth) {
        /* A fixed threshold per pad (4x4 Bayer by position): a pad steps up at its own point of a fade, so a
           slow fade looks smooth across the grid, and a pad never flips between two levels frame to frame
           (that was a 30 Hz strobe: the first version moved the threshold every frame). */
        static const uint8_t B[16] = {0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5};
        float th = ((float)B[(unsigned)(row * 4 + col) & 15u] + 0.5f) / 16.0f;
        if (frac > th) L++;
    } else if (frac >= 0.5f) L++;
    return L > 7 ? 7 : L;
}
